package tn.esprit.raghd_selmi_4act.service.impl;

import jakarta.persistence.EntityNotFoundException;
import lombok.RequiredArgsConstructor;
import org.springframework.stereotype.Service;
import tn.esprit.raghd_selmi_4act.entities.Equipement;
import tn.esprit.raghd_selmi_4act.repository.EquipementRepository;
import tn.esprit.raghd_selmi_4act.service.interfaces.IEquipementService;

import java.util.List;

@Service
@RequiredArgsConstructor
public class EquipementServiceImpl implements IEquipementService {

    // Injected by Spring (constructor injection, generated by Lombok)
    private final EquipementRepository repository;

    @Override
    public Equipement addEquipement(Equipement entity) {
        return repository.save(entity);
    }

    @Override
    public Equipement updateEquipement(Equipement entity) {
        return repository.save(entity);
    }

    @Override
    public List<Equipement> retrieveAllEquipements() {
        return repository.findAll();
    }

    @Override
    public Equipement retrieveEquipement(Long id) {
        return repository.findById(id)
                .orElseThrow(() -> new EntityNotFoundException("Equipement not found with id " + id));
    }

    @Override
    public void removeEquipement(Long id) {
        repository.deleteById(id);
    }
}
